<?php
require_once __DIR__ . '/_bootstrap.php';customerPostCsrf();if($_SERVER['REQUEST_METHOD']==='POST')customerQuery('DELETE FROM wishlist WHERE user_id=? AND product_id=?',[$customerId,(int)$_POST['product_id']]);$items=customerRows('SELECT w.product_id,p.name,p.retail_price,p.sku FROM wishlist w JOIN products p ON p.id=w.product_id WHERE w.user_id=? ORDER BY w.id DESC',[$customerId]);customerPageStart('Wishlist','Wishlist');?><div class="cw-title"><div><h1>Wishlist</h1><p>Keep products you want to source again close at hand.</p></div></div><?php if(!$items):?><div class="cw-empty">Your wishlist is empty. <a href="<?=e(BASE_URL)?>/shop/products.php">Discover products →</a></div><?php else:?><section class="cw-card"><table class="cw-table"><tr><th>Product</th><th>SKU</th><th>Price</th><th></th></tr><?php foreach($items as $i):?><tr><td><strong><?=e($i['name'])?></strong></td><td><?=e($i['sku'])?></td><td><?=e(formatPrice($i['retail_price']))?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="product_id" value="<?=(int)$i['product_id']?>"><button class="cw-btn alt">Remove</button></form></td></tr><?php endforeach;?></table></section><?php endif;?><?php customerPageEnd();?>